DROP TRIGGER trade_session_preparation_due;
--> statement-breakpoint
CREATE TRIGGER trade_session_preparation_due BEFORE INSERT ON imported_swap_preparations WHEN json_type(NEW.document,'$.session') IS NOT NULL BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM imported_trade_sessions t WHERE t.owner_id=NEW.owner_id AND t.id=json_extract(NEW.document,'$.session.sessionId') AND (json_type(t.document,'$.endsAt') IS NULL OR (json_extract(t.document,'$.strategy')='DCA' AND json_type(t.document,'$.endsAt')='text' AND julianday('now')<julianday(json_extract(t.document,'$.endsAt')))) AND ((json_type(t.document,'$.schedule') IS NULL AND json_extract(NEW.document,'$.session.format')='trade-session-entry-v1' AND json_type(NEW.document,'$.session.notBefore') IS NULL) OR ((json_extract(t.document,'$.format')='imported-trade-session-v2' OR (json_extract(t.document,'$.format')='imported-trade-session-v3' AND json_extract(t.document,'$.strategy')='DCA' AND json_extract(t.document,'$.schedule.spacingSeconds')>=1)) AND json_type(t.document,'$.schedule')='object' AND json_extract(NEW.document,'$.session.format')='trade-session-entry-v2' AND json_type(t.document,'$.schedule.spacingSeconds')='integer' AND json_extract(t.document,'$.schedule.spacingSeconds') BETWEEN 0 AND 86400 AND json_extract(NEW.document,'$.session.notBefore')=strftime('%Y-%m-%dT%H:%M:%fZ',json_extract(t.document,'$.schedule.startAt'),'+'||((json_extract(NEW.document,'$.session.entry')-1)*json_extract(t.document,'$.schedule.spacingSeconds'))||' seconds') AND julianday(strftime('%Y-%m-%dT%H:%M:%fZ',json_extract(t.document,'$.schedule.startAt'),'+'||((json_extract(NEW.document,'$.session.entry')-1)*json_extract(t.document,'$.schedule.spacingSeconds'))||' seconds'))<=julianday('now')))) THEN RAISE(ABORT,'Trade session timing differs or entry is not due') END; END;
